// Generated by vibelang from src/device/hubAccess.ts; the migrate flow writes it again with each batch.
export const withDeviceHubQuery = (url, access) => {
    const entries = Object.entries(access.query);
    if (entries.length === 0)
        return url;
    const separator = url.includes("?") ? "&" : "?";
    return `${url}${separator}${new URLSearchParams(entries).toString()}`;
};
